INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_sci_u3_L01_basic#1','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C2',1,'mc','auto','우리 주변의 식물은 대개 무엇으로 이루어져 있나요?',ARRAY['SC6-1-u3-X03']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C2","difficulty":1,"kind":"mc","stem":"우리 주변의 식물은 대개 무엇으로 이루어져 있나요?","options":[{"t":"뿌리, 줄기, 잎, 꽃 등","correct":true},{"t":"흙, 물, 햇빛 등","mis":"SC6-1-u3-X03"},{"t":"돌, 모래, 바람 등","mis":"SC6-1-u3-X03"},{"t":"사진, 이름표, 화분 등","mis":"SC6-1-u3-X03"}],"explanation":["식물을 떠올려요.","뿌리·줄기·잎·꽃이 있어요.","식물은 이것들로 이루어져요."]}'::jsonb),
('g6_1_sci_u3_L01_basic#2','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C1',1,'ox','auto','다섯 고개 놀이에서는 식물의 생김새나 구조에 관한 질문만 할 수 있어요.',ARRAY['SC6-1-u3-X01']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C1","difficulty":1,"kind":"ox","stem":"다섯 고개 놀이에서는 식물의 생김새나 구조에 관한 질문만 할 수 있어요.","answer":"O","reason_options":[{"t":"질문을 식물의 생김새나 구조에 관한 것으로 정해 두었기 때문에","correct":true},{"t":"어떤 질문이든 마음대로 해도 되기 때문에","mis":"SC6-1-u3-X01"}],"mis":"SC6-1-u3-X01","explanation":["질문에 약속이 있어요.","생김새나 구조만 물어요.","맞는 말이에요."]}'::jsonb),
('g6_1_sci_u3_L01_basic#3','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C3',1,'mc','auto','식물에 앨러지가 있는 친구가 식물을 살펴볼 때 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X04']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C3","difficulty":1,"kind":"mc","stem":"식물에 앨러지가 있는 친구가 식물을 살펴볼 때 알맞은 것은 어느 것인가요?","options":[{"t":"식물을 직접 만지지 않고 눈으로 살펴본다","correct":true},{"t":"잎을 따서 냄새를 맡아 본다","mis":"SC6-1-u3-X04"},{"t":"꽃을 꺾어 교실로 가져간다","mis":"SC6-1-u3-X04"},{"t":"나무에 올라가 가까이 본다","mis":"SC6-1-u3-X04"}],"explanation":["앨러지가 있어요.","직접 만지지 않아요.","눈으로 살펴봐요."]}'::jsonb),
('g6_1_sci_u3_L01_basic#4','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C2',1,'sa','auto','식물에서 주로 땅속에 있어 사진에 잘 보이지 않는 부분의 이름을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u3-C2","difficulty":1,"kind":"sa","stem":"식물에서 주로 땅속에 있어 사진에 잘 보이지 않는 부분의 이름을 두 글자로 쓰세요.","answer":["뿌리"],"explanation":["땅속에 있어요.","두 글자예요.","뿌리예요."],"mis":"SC6-1-u3-X03"}'::jsonb),
('g6_1_sci_u3_L01_basic#5','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C1',2,'mc','auto','다섯 고개 놀이에서 다른 모둠에게 식물 사진을 보여 주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X02','SC6-1-u3-X04']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C1","difficulty":2,"kind":"mc","stem":"다섯 고개 놀이에서 다른 모둠에게 식물 사진을 보여 주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"사진의 일부분만 보여 준다","correct":true},{"t":"사진 전체와 식물 이름을 함께 보여 준다","mis":"SC6-1-u3-X02"},{"t":"사진은 보여 주지 않고 이름만 알려 준다","mis":"SC6-1-u3-X02"},{"t":"식물을 뽑아서 통째로 보여 준다","mis":"SC6-1-u3-X04"}],"explanation":["맞혀야 하는 놀이예요.","일부분만 보여 줘요.","그래서 질문이 필요해요."]}'::jsonb),
('g6_1_sci_u3_L01_basic#6','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C1',2,'mc','auto','다섯 고개 질문으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X01']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C1","difficulty":2,"kind":"mc","stem":"다섯 고개 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「잎은 어떤 모양인가요?」","correct":true},{"t":"「이 식물은 얼마에 살 수 있나요?」","mis":"SC6-1-u3-X01"},{"t":"「이 식물을 누가 좋아하나요?」","mis":"SC6-1-u3-X01"},{"t":"「이 식물은 무슨 맛인가요?」","mis":"SC6-1-u3-X01"}],"explanation":["생김새를 물어요.","잎 모양은 생김새예요.","값·맛은 안 돼요."]}'::jsonb),
('g6_1_sci_u3_L01_basic#7','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C2',2,'mc','auto','우리 학교 식물 관찰 기록에서 소나무에 대해 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X03']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C2","difficulty":2,"kind":"mc","stem":"우리 학교 식물 관찰 기록에서 소나무에 대해 알 수 있는 것은 어느 것인가요?","options":[{"t":"줄기가 적갈색이고 바늘 모양 잎이 두 개씩 모여 달린다","correct":true},{"t":"꽃이 노란색이고 꽃잎이 다섯 장이다","mis":"SC6-1-u3-X03"},{"t":"뿌리가 땅 위로 드러나 잘 보인다","mis":"SC6-1-u3-X03"},{"t":"모든 식물과 생김새가 똑같다","mis":"SC6-1-u3-X03"}],"explanation":["소나무 줄을 봐요.","적갈색 줄기예요.","바늘 모양 잎이 두 개씩이에요."],"asset":{"type":"passage","lines":["정문 옆 소나무 — 줄기는 적갈색, 바늘 모양 잎이 두 개씩 모여 달림","화단의 애기똥풀 — 꽃이 노란색","울타리의 무궁화 — 꽃잎이 다섯 장","화단의 민들레 — 뿌리는 땅속에 있어 보이지 않음"],"title":"우리 학교 식물 관찰 기록"}}'::jsonb),
('g6_1_sci_u3_L01_basic#8','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C3',2,'mc','auto','식물 이름 찾기 애플리케이션으로 이름을 알아낸 뒤 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X05','SC6-1-u3-X04']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C3","difficulty":2,"kind":"mc","stem":"식물 이름 찾기 애플리케이션으로 이름을 알아낸 뒤 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"식물도감으로 정확한 정보인지 확인한다","correct":true},{"t":"애플리케이션 결과는 늘 맞으니 그대로 적는다","mis":"SC6-1-u3-X05"},{"t":"수업과 상관없는 동영상을 찾아본다","mis":"SC6-1-u3-X05"},{"t":"식물을 뽑아 들고 다시 찍는다","mis":"SC6-1-u3-X04"}],"explanation":["결과가 틀릴 수도 있어요.","도감으로 확인해요.","정확한 정보를 써요."]}'::jsonb),
('g6_1_sci_u3_L01_basic#9','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C2',2,'ox','auto','식물은 종류가 달라도 잎과 꽃의 생김새가 모두 같아요.',ARRAY['SC6-1-u3-X03']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C2","difficulty":2,"kind":"ox","stem":"식물은 종류가 달라도 잎과 꽃의 생김새가 모두 같아요.","answer":"X","reason_options":[{"t":"식물마다 줄기·잎·꽃의 모양이 매우 다양하기 때문에","correct":true},{"t":"식물은 모두 같은 모양으로 자라기 때문에","mis":"SC6-1-u3-X03"}],"mis":"SC6-1-u3-X03","explanation":["여러 식물을 떠올려요.","모양이 서로 달라요.","틀린 말이에요."]}'::jsonb),
('g6_1_sci_u3_L01_basic#10','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C3',3,'error','auto','화단에서 식물을 살펴보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X04']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C3","difficulty":3,"kind":"error","stem":"화단에서 식물을 살펴보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준혁 — 「더 잘 보려면 나무 위로 올라가서 살펴보자.」","correct":true,"mis_target":"SC6-1-u3-X04"},{"t":"아린 — 「식물이 다치지 않게 잎을 함부로 따지 말자.」","mis":"SC6-1-u3-X04"},{"t":"태민 — 「가시에 얼굴이 긁히지 않게 조심하자.」","mis":"SC6-1-u3-X04"}],"explanation":["위험한 곳은 안 돼요.","나무에 오르지 않아요.","준혁의 말이 잘못됐어요."]}'::jsonb),
('g6_1_sci_u3_L01_challenge#1','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C2',2,'match','auto','우리 학교 식물 관찰 기록에서 식물과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C2","difficulty":2,"kind":"match","stem":"우리 학교 식물 관찰 기록에서 식물과 특징을 알맞게 이으세요.","pairs":[{"l":"소나무","r":"바늘 모양 잎이 두 개씩 모여 달림"},{"l":"애기똥풀","r":"꽃이 노란색"},{"l":"무궁화","r":"꽃잎이 다섯 장"}],"mis":"SC6-1-u3-X03","explanation":["기록을 봐요.","식물마다 특징이 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["정문 옆 소나무 — 줄기는 적갈색, 바늘 모양 잎이 두 개씩 모여 달림","화단의 애기똥풀 — 꽃이 노란색","울타리의 무궁화 — 꽃잎이 다섯 장","화단의 민들레 — 뿌리는 땅속에 있어 보이지 않음"],"title":"우리 학교 식물 관찰 기록"}}'::jsonb),
('g6_1_sci_u3_L01_challenge#2','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',2,'mc','auto','다섯 고개 놀이에서 질문을 다섯 번 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X01','SC6-1-u3-X02']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C1","difficulty":2,"kind":"mc","stem":"다섯 고개 놀이에서 질문을 다섯 번 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"식물의 생김새와 구조를 하나씩 좁혀 가며 이름을 알아내려고","correct":true},{"t":"식물의 값을 알아내려고","mis":"SC6-1-u3-X01"},{"t":"사진 전체를 보여 달라고 하려고","mis":"SC6-1-u3-X02"},{"t":"질문 수와 상관없이 처음부터 이름을 말하려고","mis":"SC6-1-u3-X02"}],"explanation":["일부분만 보여요.","질문으로 좁혀 가요.","그래서 다섯 번 물어요."]}'::jsonb),
('g6_1_sci_u3_L01_challenge#3','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',3,'mc','auto','다섯 고개 놀이 메모의 ㉠~㉤을 바른 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X02']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C1","difficulty":3,"kind":"mc","stem":"다섯 고개 놀이 메모의 ㉠~㉤을 바른 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉤ → ㉢ → ㉠","correct":true},{"t":"㉤ → ㉡ → ㉣ → ㉠ → ㉢","mis":"SC6-1-u3-X02"},{"t":"㉡ → ㉢ → ㉤ → ㉣ → ㉠","mis":"SC6-1-u3-X02"},{"t":"㉣ → ㉡ → ㉠ → ㉤ → ㉢","mis":"SC6-1-u3-X02"}],"explanation":["먼저 화단을 살펴요.","이름 확인 뒤 사진을 찍어요.","일부분을 보여 주고 맞혀요."],"asset":{"type":"passage","lines":["㉠ 다른 모둠은 다섯 가지 질문을 한 뒤 식물 이름을 맞힌다.","㉡ 화단의 한 구역을 정해 식물을 살펴본다.","㉢ 다른 모둠에게 식물 사진의 일부분을 보여 준다.","㉣ 스마트 기기나 식물도감으로 식물 이름을 확인한다.","㉤ 모둠원과 문제로 낼 식물을 정해 사진을 찍는다."],"title":"다섯 고개 놀이 메모(차례가 섞임)"}}'::jsonb),
('g6_1_sci_u3_L01_challenge#4','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',3,'mc','auto','우리 모둠이 준비한 다섯 고개 질문 가운데 바꾸어야 할 것은 어느 것인가요?',ARRAY['SC6-1-u3-X01']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C1","difficulty":3,"kind":"mc","stem":"우리 모둠이 준비한 다섯 고개 질문 가운데 바꾸어야 할 것은 어느 것인가요?","options":[{"t":"③","correct":true},{"t":"①","mis":"SC6-1-u3-X01"},{"t":"②","mis":"SC6-1-u3-X01"},{"t":"⑤","mis":"SC6-1-u3-X01"}],"explanation":["생김새를 묻나요?","③은 값을 물어요.","③을 바꿔야 해요."],"asset":{"type":"passage","lines":["① 나보다 키가 큰 식물인가요?","② 꽃잎이 몇 장인가요?","③ 이 식물은 얼마에 살 수 있나요?","④ 잎은 어떤 모양인가요?","⑤ 줄기에 가시가 있나요?"],"title":"우리 모둠이 준비한 다섯 고개 질문"}}'::jsonb),
('g6_1_sci_u3_L01_challenge#5','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',3,'mc','auto','우리 모둠이 준비한 다섯 고개 질문의 ③을 바꾼 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X01','SC6-1-u3-X02']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C1","difficulty":3,"kind":"mc","stem":"우리 모둠이 준비한 다섯 고개 질문의 ③을 바꾼 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「열매의 크기는 어느 정도인가요?」","correct":true},{"t":"「이 식물은 어디에서 팔까요?」","mis":"SC6-1-u3-X01"},{"t":"「이 식물로 무엇을 요리하나요?」","mis":"SC6-1-u3-X01"},{"t":"「이 식물 이름은 무엇인가요?」","mis":"SC6-1-u3-X02"}],"explanation":["생김새로 바꿔요.","열매 크기는 생김새예요.","알맞게 바꿨어요."],"asset":{"type":"passage","lines":["① 나보다 키가 큰 식물인가요?","② 꽃잎이 몇 장인가요?","③ 이 식물은 얼마에 살 수 있나요?","④ 잎은 어떤 모양인가요?","⑤ 줄기에 가시가 있나요?"],"title":"우리 모둠이 준비한 다섯 고개 질문"}}'::jsonb),
('g6_1_sci_u3_L01_challenge#6','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C3',3,'error','auto','식물 이름을 알아보는 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X05']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C3","difficulty":3,"kind":"error","stem":"식물 이름을 알아보는 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「애플리케이션이 알려 줬으니 도감은 안 봐도 돼.」","correct":true,"mis_target":"SC6-1-u3-X05"},{"t":"지호 — 「비슷한 특징이 있는 식물을 도감에서 찾아 확인하자.」","mis":"SC6-1-u3-X05"},{"t":"하율 — 「수업과 관련 없는 누리집은 열지 말자.」","mis":"SC6-1-u3-X05"}],"explanation":["확인이 필요해요.","도감과 견줘요.","민서의 말이 잘못됐어요."]}'::jsonb),
('g6_1_sci_u3_L01_challenge#7','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C3',3,'ox','auto','꽃가루 앨러지가 있는 친구는 식물을 살펴볼 때 마스크를 쓰는 것이 좋아요.',ARRAY['SC6-1-u3-X04']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C3","difficulty":3,"kind":"ox","stem":"꽃가루 앨러지가 있는 친구는 식물을 살펴볼 때 마스크를 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"꽃가루 때문에 몸에 이상이 생기는 것을 막을 수 있기 때문에","correct":true},{"t":"마스크를 쓰면 식물 이름을 더 빨리 맞힐 수 있기 때문에","mis":"SC6-1-u3-X04"}],"mis":"SC6-1-u3-X04","explanation":["앨러지가 있어요.","꽃가루를 막아요.","마스크를 써요."]}'::jsonb),
('g6_1_sci_u3_L01_challenge#8','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C2',4,'mc','auto','우리 학교 식물 관찰 기록에서 민들레만 다섯 고개 질문을 「뿌리」로 만들기 어려운 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X03','SC6-1-u3-X01']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C2","difficulty":4,"kind":"mc","stem":"우리 학교 식물 관찰 기록에서 민들레만 다섯 고개 질문을 「뿌리」로 만들기 어려운 까닭은 무엇인가요?","options":[{"t":"뿌리가 땅속에 있어 사진에 보이지 않기 때문이다","correct":true},{"t":"민들레는 뿌리가 없는 식물이기 때문이다","mis":"SC6-1-u3-X03"},{"t":"뿌리는 모든 식물이 똑같이 생겼기 때문이다","mis":"SC6-1-u3-X03"},{"t":"뿌리에 관한 질문은 생김새가 아니기 때문이다","mis":"SC6-1-u3-X01"}],"explanation":["뿌리는 어디 있나요?","땅속이라 안 보여요.","사진으로 묻기 어려워요."],"asset":{"type":"passage","lines":["정문 옆 소나무 — 줄기는 적갈색, 바늘 모양 잎이 두 개씩 모여 달림","화단의 애기똥풀 — 꽃이 노란색","울타리의 무궁화 — 꽃잎이 다섯 장","화단의 민들레 — 뿌리는 땅속에 있어 보이지 않음"],"title":"우리 학교 식물 관찰 기록"}}'::jsonb),
('g6_1_sci_u3_L01_challenge#9','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C3',4,'mc','auto','모둠이 문제로 낼 식물 사진을 찍으려고 해요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC6-1-u3-X04']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C3","difficulty":4,"kind":"mc","stem":"모둠이 문제로 낼 식물 사진을 찍으려고 해요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"식물을 그대로 둔 채 줄기·잎·꽃이 보이게 찍는다","correct":true},{"t":"잘 보이게 꽃과 잎을 따서 책상에 모아 찍는다","mis":"SC6-1-u3-X04"},{"t":"높이 있는 꽃을 찍으려고 울타리에 올라간다","mis":"SC6-1-u3-X04"},{"t":"식물을 뽑아 뿌리까지 찍어 다시 버려 둔다","mis":"SC6-1-u3-X04"}],"explanation":["식물을 아껴요.","그대로 둔 채 찍어요.","안전하게 찍어요."]}'::jsonb),
