('g6_1_sci_u3_L08_basic#7','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C27',2,'mc','auto','잎에 도달한 물의 일부는 어떻게 되나요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X50','SC6-1-u3-X48']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C27","difficulty":2,"kind":"mc","stem":"잎에 도달한 물의 일부는 어떻게 되나요?","options":[{"t":"기공을 통해 식물 밖으로 빠져나간다","correct":true},{"t":"뿌리로 다시 내려가 땅에 버려진다","mis":"SC6-1-u3-X49"},{"t":"모두 열매에 저장된다","mis":"SC6-1-u3-X50"},{"t":"꽃가루로 바뀐다","mis":"SC6-1-u3-X48"}],"explanation":["잎까지 온 물이에요.","일부가 나가요.","기공을 통해 나가요."]}'::jsonb),
('g6_1_sci_u3_L08_basic#8','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C29',2,'mc','auto','시계의 톱니바퀴 하나가 빠지면 시계가 멈추는 것처럼, 식물의 한 기관에 문제가 생기면 어떻게 될 수 있나요?',ARRAY['SC6-1-u3-X48','SC6-1-u3-X22']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C29","difficulty":2,"kind":"mc","stem":"시계의 톱니바퀴 하나가 빠지면 시계가 멈추는 것처럼, 식물의 한 기관에 문제가 생기면 어떻게 될 수 있나요?","options":[{"t":"식물 전체의 생명활동에 문제가 생길 수 있다","correct":true},{"t":"다른 기관은 아무 영향을 받지 않는다","mis":"SC6-1-u3-X48"},{"t":"문제가 생긴 기관만 없어지고 나머지는 더 잘 자란다","mis":"SC6-1-u3-X48"},{"t":"잎이 대신 물을 흡수해 준다","mis":"SC6-1-u3-X22"}],"explanation":["톱니바퀴를 떠올려요.","기관은 연결되어 있어요.","전체에 영향을 줘요."]}'::jsonb),
