('g6_1_sci_u3_L09_basic#5','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C30',2,'mc','auto','우리 반 식물도감 카드에서 토끼풀의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C30","difficulty":2,"kind":"mc","stem":"우리 반 식물도감 카드에서 토끼풀의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄기가 땅 위를 기듯이 자라고 잎이 세 갈래로 갈라진다","correct":true},{"t":"바늘 모양 잎이 두 개씩 모여 난다","mis":"SC6-1-u3-X52"},{"t":"줄기나 잎을 자르면 노란 즙이 나온다","mis":"SC6-1-u3-X52"},{"t":"보라색 꽃의 꽃잎 모양이 서로 다르다","mis":"SC6-1-u3-X52"}],"explanation":["토끼풀 줄을 봐요.","땅 위를 기어요.","잎이 세 갈래예요."],"asset":{"type":"passage","lines":["소나무 — 바늘 모양 잎이 두 개씩 모여 난다. 봄에 노란 꽃가루가 날린다.","애기똥풀 — 노란 꽃이 핀다. 줄기나 잎을 자르면 노란 즙이 나온다.","제비꽃 — 보라색 꽃이 핀다. 꽃잎 모양이 서로 다르고 잎자루가 길다.","토끼풀 — 줄기가 땅 위를 기듯이 자라고 잎은 세 갈래로 갈라진다.","토끼풀 — 여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다."],"title":"우리 반 식물도감 카드"}}'::jsonb),
('g6_1_sci_u3_L09_basic#6','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C30',2,'mc','auto','식물 소개 자료에 꼭 들어가야 할 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C30","difficulty":2,"kind":"mc","stem":"식물 소개 자료에 꼭 들어가야 할 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뿌리·줄기·잎·꽃 등의 구조와 기능에 관한 설명","correct":true},{"t":"식물을 파는 가게와 값","mis":"SC6-1-u3-X52"},{"t":"식물 사진 한 장만","mis":"SC6-1-u3-X52"},{"t":"그 식물을 좋아하는 친구 이름","mis":"SC6-1-u3-X52"}],"explanation":["도감은 무엇을 알려 주나요?","식물의 특징이에요.","구조와 기능을 넣어요."]}'::jsonb),
