('g6_1_sci_u3_L09_challenge#3','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C32',3,'mc','auto','오래된 땅속에서 찾은 꽃가루로 그때의 식물과 날씨를 알아낼 수 있는 까닭은 꽃가루의 어떤 특징 때문인가요?',ARRAY['SC6-1-u3-X55','SC6-1-u3-X54']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C32","difficulty":3,"kind":"mc","stem":"오래된 땅속에서 찾은 꽃가루로 그때의 식물과 날씨를 알아낼 수 있는 까닭은 꽃가루의 어떤 특징 때문인가요?","options":[{"t":"모양이 잘 변하지 않고 식물마다 모양이 달라서","correct":true},{"t":"크기가 커서 쉽게 눈에 띄어서","mis":"SC6-1-u3-X55"},{"t":"모든 식물의 꽃가루가 같은 모양이어서","mis":"SC6-1-u3-X55"},{"t":"꽃가루가 앨러지를 일으켜서","mis":"SC6-1-u3-X54"}],"explanation":["오래 남아 있어요.","모양이 달라 구별돼요.","그래서 알 수 있어요."],"asset":{"type":"passage","lines":["꽃가루는 크기가 매우 작고 식물마다 모양이 다르다.","꽃가루는 모양이 잘 변하지 않고 오래 남는다.","해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 나왔다.","사건 증거품에 묻은 꽃가루로 사건 장소를 찾기도 한다.","오래된 땅속 꽃가루로 그때 자란 식물과 날씨를 알아낸다."],"title":"만능 재주꾼, 꽃가루"}}'::jsonb),
('g6_1_sci_u3_L09_challenge#4','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C32',3,'mc','auto','해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 의료용으로도 쓰일 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X54','SC6-1-u3-X55','SC6-1-u3-X45']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C32","difficulty":3,"kind":"mc","stem":"해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 의료용으로도 쓰일 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"구하기 쉽고 독성이 없기 때문이다","correct":true},{"t":"꽃가루는 모두 앨러지를 일으키기 때문이다","mis":"SC6-1-u3-X54"},{"t":"꽃가루가 아주 크고 모양이 같기 때문이다","mis":"SC6-1-u3-X55"},{"t":"꽃가루가 양분을 만들기 때문이다","mis":"SC6-1-u3-X45"}],"explanation":["사람 몸에 써요.","해롭지 않아야 해요.","독성이 없어요."]}'::jsonb),
('g6_1_sci_u3_L09_challenge#5','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C30',3,'mc','auto','토끼풀 소개 자료에 「여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다」를 넣었어요. 이것은 어떤 내용을 담은 것인가요?',ARRAY['SC6-1-u3-X52','SC6-1-u3-X53']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C30","difficulty":3,"kind":"mc","stem":"토끼풀 소개 자료에 「여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다」를 넣었어요. 이것은 어떤 내용을 담은 것인가요?","options":[{"t":"다른 식물과 견주어 특이한 꽃의 구조","correct":true},{"t":"토끼풀을 파는 곳","mis":"SC6-1-u3-X52"},{"t":"토끼풀을 좋아하는 까닭","mis":"SC6-1-u3-X52"},{"t":"출처를 밝히지 않은 소문","mis":"SC6-1-u3-X53"}],"explanation":["꽃의 생김새예요.","특이한 점이에요.","구조를 담았어요."],"asset":{"type":"passage","lines":["소나무 — 바늘 모양 잎이 두 개씩 모여 난다. 봄에 노란 꽃가루가 날린다.","애기똥풀 — 노란 꽃이 핀다. 줄기나 잎을 자르면 노란 즙이 나온다.","제비꽃 — 보라색 꽃이 핀다. 꽃잎 모양이 서로 다르고 잎자루가 길다.","토끼풀 — 줄기가 땅 위를 기듯이 자라고 잎은 세 갈래로 갈라진다.","토끼풀 — 여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다."],"title":"우리 반 식물도감 카드"}}'::jsonb),
('g6_1_sci_u3_L09_challenge#6','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C32',3,'error','auto','꽃가루를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X54']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C32","difficulty":3,"kind":"error","stem":"꽃가루를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「꽃가루는 콧물만 나게 하니까 세상에서 없어지면 좋겠어.」","correct":true,"mis_target":"SC6-1-u3-X54"},{"t":"건우 — 「꽃가루받이에 꽃가루가 꼭 필요해.」","mis":"SC6-1-u3-X54"},{"t":"채린 — 「꽃가루로 사건 장소를 찾기도 한대.」","mis":"SC6-1-u3-X54"}],"explanation":["꽃가루가 하는 일이 있어요.","쓰임도 많아요.","로아의 말이 잘못됐어요."]}'::jsonb),
('g6_1_sci_u3_L09_challenge#7','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C30',3,'ox','auto','식물 소개 자료에는 식물의 생김새 사진만 넣으면 충분해요.',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C30","difficulty":3,"kind":"ox","stem":"식물 소개 자료에는 식물의 생김새 사진만 넣으면 충분해요.","answer":"X","reason_options":[{"t":"식물의 구조와 기능이 잘 드러나도록 설명도 함께 넣어야 하기 때문에","correct":true},{"t":"사진을 넣으면 출처를 밝히지 않아도 되기 때문에","mis":"SC6-1-u3-X52"}],"mis":"SC6-1-u3-X52","explanation":["도감은 무엇을 알려 주나요?","구조와 기능이에요.","설명도 넣어요."]}'::jsonb),
('g6_1_sci_u3_L09_challenge#8','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C31',4,'mc','auto','친구가 공유 플랫폼에 올린 식물 소개 자료를 보고 남길 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X53','SC6-1-u3-X52']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C31","difficulty":4,"kind":"mc","stem":"친구가 공유 플랫폼에 올린 식물 소개 자료를 보고 남길 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「채송화 꽃이 밤에 오므라든다는 걸 처음 알았어. 사진도 잘 골랐다.」","correct":true},{"t":"「출처는 필요 없으니 지우는 게 좋겠어.」","mis":"SC6-1-u3-X53"},{"t":"「내가 조사한 식물이랑 똑같이 고쳐.」","mis":"SC6-1-u3-X52"},{"t":"「사진만 있으면 되지, 설명은 왜 넣었어?」","mis":"SC6-1-u3-X52"}],"explanation":["새로 안 점을 말해요.","잘한 점을 찾아요.","고운 말로 남겨요."]}'::jsonb),
('g6_1_sci_u3_L09_challenge#9','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C33',4,'mc','auto','사과나무와 토끼풀을 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X56','SC6-1-u3-X06']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C33","difficulty":4,"kind":"mc","stem":"사과나무와 토끼풀을 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"생김새와 크기는 매우 다르지만 둘 다 뿌리·줄기·잎·꽃 등의 기관으로 이루어져 있다","correct":true},{"t":"크기가 다르니 사과나무만 기관이 있다","mis":"SC6-1-u3-X56"},{"t":"토끼풀은 너무 작아 세포로 이루어져 있지 않다","mis":"SC6-1-u3-X06"},{"t":"두 식물은 뿌리가 하는 일이 정반대다","mis":"SC6-1-u3-X56"}],"explanation":["크기는 달라요.","기관을 떠올려요.","기관은 비슷해요."]}'::jsonb),
('g6_1_sci_u3_L09_challenge#10','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C32',4,'essay','teacher','내가 과학자라면 꽃가루의 특징을 이용해 무엇을 만들거나 연구하고 싶은지, 그 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C32","difficulty":4,"kind":"essay","stem":"내가 과학자라면 꽃가루의 특징을 이용해 무엇을 만들거나 연구하고 싶은지, 그 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 꽃가루는 식물마다 모양이 다르고 잘 변하지 않으니, 우리 동네 땅속 꽃가루를 모아 옛날에 어떤 식물이 자랐는지 알아보는 지도를 만들고 싶다.","scoring_points":["꽃가루의 특징(작음·모양이 다름·잘 변하지 않음 등)을 썼는가","그 특징을 이용한 쓰임을 썼는가"]},"explanation":["꽃가루의 특징을 떠올려요.","쓰임을 상상해요.","까닭과 함께 써요."]}'::jsonb),
('g6_1_sci_u3_review_a#1','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C1',1,'mc','auto','초록잎반 탐구 일지 ①에서 다른 모둠이 한 질문은 식물의 무엇에 관한 것인가요?',ARRAY['SC6-1-u3-X01']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C1","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ①에서 다른 모둠이 한 질문은 식물의 무엇에 관한 것인가요?","options":[{"t":"생김새","correct":true},{"t":"값","mis":"SC6-1-u3-X01"},{"t":"맛","mis":"SC6-1-u3-X01"},{"t":"기르는 사람","mis":"SC6-1-u3-X01"}],"explanation":["질문을 읽어요.","키와 꽃 색이에요.","생김새를 물었어요."],"asset":{"type":"passage","lines":["우리 모둠은 화단의 해바라기를 다섯 고개 문제로 냈다.","사진은 꽃잎 부분만 잘라서 보여 주었다.","다른 모둠은 「나보다 키가 큰가요?」, 「꽃은 무슨 색인가요?」 등을 물었다.","앱으로 알아낸 이름은 식물도감으로 다시 확인했다."],"title":"① 다섯 고개 놀이"}}'::jsonb),
