('g6_1_soc_u1_L06_challenge#2','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',2,'ox','auto','5·18 민주화 운동은 우리나라뿐 아니라 세계 여러 나라의 민주화 운동에도 영향을 주었어요.',ARRAY['SO6-1-u1-X20']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"ox","stem":"5·18 민주화 운동은 우리나라뿐 아니라 세계 여러 나라의 민주화 운동에도 영향을 주었어요.","answer":"O","reason_options":[{"t":"폭력에 맞서 민주주의를 지키려 한 시민의 의지가 널리 알려졌기 때문에","correct":true},{"t":"광주 한 도시 안에서만 기억되고 끝난 일이기 때문에","mis":"SO6-1-u1-X20"}],"mis":"SO6-1-u1-X20","explanation":["진실이 세계에 알려졌어요.","여러 나라에 영향을 주었어요.","그래서 O예요."]}'::jsonb),
('g6_1_soc_u1_L06_challenge#3','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',3,'mc','auto','흐름 메모의 ④와 ⑤를 견주어 보았을 때 가장 알맞은 설명은 어느 것인가요?',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"mc","stem":"흐름 메모의 ④와 ⑤를 견주어 보았을 때 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"시민은 바깥에 알리려 했고, 계엄군은 알려지지 않게 막았다","correct":true},{"t":"시민과 계엄군 모두 바깥에 알리려 했다","mis":"SO6-1-u1-X19"},{"t":"계엄군은 알리려 했고 시민은 숨기려 했다","mis":"SO6-1-u1-X19"},{"t":"둘 다 바깥과 아무 관계가 없었다","mis":"SO6-1-u1-X19"}],"explanation":["④는 시민의 일이에요.","⑤는 계엄군의 일이에요.","알리려는 쪽과 막는 쪽이에요."],"asset":{"type":"passage","lines":["① 군인들이 정변을 일으켜 다시 권력을 차지했다.","② 시민들이 군인들의 퇴진과 민주화를 요구했다.","③ 광주에서 큰 민주화 시위가 일어나자 계엄군이 들어왔다.","④ 시민들은 시민군을 만들어 맞서고 바깥에 알리려 했다.","⑤ 계엄군은 길을 막고 신문과 방송을 통제했다.","⑥ 외국인 기자들이 광주의 일을 영상과 사진에 담아 세계에 알렸다."],"title":"5·18 민주화 운동 흐름 메모"}}'::jsonb),
