('g6_1_soc_u1_review_d#16','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C16',2,'mc','auto','라디오와 텔레비전이 널리 보급되면서 성장한 것은 무엇인가요?',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":16,"concept":"SO6-1-u1-C16","difficulty":2,"kind":"mc","stem":"라디오와 텔레비전이 널리 보급되면서 성장한 것은 무엇인가요?","options":[{"t":"가요·영화·드라마·스포츠 같은 대중문화","correct":true},{"t":"농촌 인구","mis":"SO6-1-u1-X28"},{"t":"달동네","mis":"SO6-1-u1-X28"},{"t":"간선제","mis":"SO6-1-u1-X28"}],"explanation":["대중 매체가 보급됐어요.","많은 사람이 함께 즐겨요.","대중문화가 성장했어요."]}'::jsonb),
('g6_1_soc_u1_review_d#17','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C4',3,'ox','auto','신문 ②의 모둠처럼 답사를 마친 뒤 알게 된 것과 처음 짐작을 견주어 보는 것이 좋아요.',ARRAY['SO6-1-u1-X08']::text[],false,'{"seq":17,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"ox","stem":"신문 ②의 모둠처럼 답사를 마친 뒤 알게 된 것과 처음 짐작을 견주어 보는 것이 좋아요.","answer":"O","reason_options":[{"t":"답사는 가서 알게 되는 일이라 짐작이 어떻게 바뀌었는지 확인할 수 있기 때문에","correct":true},{"t":"처음 짐작은 언제나 틀리기 때문에","mis":"SO6-1-u1-X08"}],"mis":"SO6-1-u1-X08","explanation":["답사는 알게 되는 일이에요.","짐작이 바뀌어요.","견주어 봐요."],"asset":{"type":"passage","lines":["우리 모둠은 인터넷으로 DMZ 평화의 길을 답사했다.","누리집에서 그곳의 의미, 있었던 일, 주요 시설을 차례로 살폈다.","희귀한 새와 식물 사진이 많아 모두 놀랐다.","통일 뒤에는 이곳을 평화 생태 학습장으로 만들자고 기사에 썼다."],"title":"햇살반 역사 신문 ② 답사 기사"}}'::jsonb),
('g6_1_soc_u1_review_d#18','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C7',3,'ox','auto','남북 경제 협력 사업은 평화 통일을 이루는 밑바탕이 될 수 있어요.',ARRAY['SO6-1-u1-X12']::text[],false,'{"seq":18,"concept":"SO6-1-u1-C7","difficulty":3,"kind":"ox","stem":"남북 경제 협력 사업은 평화 통일을 이루는 밑바탕이 될 수 있어요.","answer":"O","reason_options":[{"t":"함께 일하며 서로 잘 살게 되면 믿음이 쌓이기 때문에","correct":true},{"t":"경제 협력은 통일과 아무 관계가 없기 때문에","mis":"SO6-1-u1-X12"}],"mis":"SO6-1-u1-X12","explanation":["함께 일해요.","믿음이 쌓여요.","통일의 밑바탕이에요."]}'::jsonb),
('g6_1_soc_u1_review_d#19','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C9',3,'ox','auto','세 민주화 운동은 날짜와 숫자만 외우면 충분히 이해할 수 있어요.',ARRAY['SO6-1-u1-X31']::text[],false,'{"seq":19,"concept":"SO6-1-u1-C9","difficulty":3,"kind":"ox","stem":"세 민주화 운동은 날짜와 숫자만 외우면 충분히 이해할 수 있어요.","answer":"X","reason_options":[{"t":"각 사건이 왜 일어나 어떤 결과를 낳았는지 원인과 결과를 이어야 이해할 수 있기 때문에","correct":true},{"t":"민주화 운동에는 원인이 없기 때문에","mis":"SO6-1-u1-X31"}],"mis":"SO6-1-u1-X31","explanation":["외우기만으로는 부족해요.","원인과 결과를 이어요.","그래서 X예요."]}'::jsonb),
('g6_1_soc_u1_review_d#20','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C13',3,'ox','auto','신문 ⑥에서 할머니가 하천 지킴이로 활동하시는 것은 시민이 사회문제 해결에 참여하는 모습이에요.',ARRAY['SO6-1-u1-X23']::text[],false,'{"seq":20,"concept":"SO6-1-u1-C13","difficulty":3,"kind":"ox","stem":"신문 ⑥에서 할머니가 하천 지킴이로 활동하시는 것은 시민이 사회문제 해결에 참여하는 모습이에요.","answer":"O","reason_options":[{"t":"시민 단체를 통해 지역의 문제를 함께 해결하려는 활동이기 때문에","correct":true},{"t":"하천 지킴이는 대통령을 뽑는 일이기 때문에","mis":"SO6-1-u1-X23"}],"mis":"SO6-1-u1-X23","explanation":["시민 단체 활동이에요.","하천 문제를 함께 풀어요.","시민 참여예요."],"asset":{"type":"passage","lines":["할머니는 대통령을 처음 직접 뽑던 날을 또렷이 기억하신다.","투표소 앞에 줄이 길게 늘어섰는데도 모두 웃는 얼굴이었다고 했다.","요즘은 우리 지역의 대표도 주민이 직접 뽑는다.","할머니는 시민 단체에서 하천 지킴이로 활동하신다."],"title":"햇살반 역사 신문 ⑥ 할머니의 투표 날"}}'::jsonb),
('g6_1_soc_u1_review_d#21','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C15',3,'ox','auto','같은 라면이라도 먹을거리가 모자라던 때와 오늘날 만든 목적이 달라요.',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":21,"concept":"SO6-1-u1-C15","difficulty":3,"kind":"ox","stem":"같은 라면이라도 먹을거리가 모자라던 때와 오늘날 만든 목적이 달라요.","answer":"O","reason_options":[{"t":"옛날에는 식량 부족을 해결하려고, 오늘날에는 수출 상품으로 만들기 때문에","correct":true},{"t":"라면은 언제나 같은 목적으로만 만들기 때문에","mis":"SO6-1-u1-X27"}],"mis":"SO6-1-u1-X27","explanation":["시대 상황이 달라요.","목적도 달라졌어요.","그래서 O예요."]}'::jsonb),
('g6_1_soc_u1_review_d#22','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C17',3,'ox','auto','산업화 시기에 많은 사람이 근무 환경 개선과 임금 인상 등 근로자의 권리를 보호하려고 노력했어요.',ARRAY['SO6-1-u1-X30']::text[],false,'{"seq":22,"concept":"SO6-1-u1-C17","difficulty":3,"kind":"ox","stem":"산업화 시기에 많은 사람이 근무 환경 개선과 임금 인상 등 근로자의 권리를 보호하려고 노력했어요.","answer":"O","reason_options":[{"t":"근로자들이 열악한 환경에서 오래 일하자 그 권리를 지키려는 목소리가 커졌기 때문에","correct":true},{"t":"근로자의 권리는 아무도 관심을 두지 않았기 때문에","mis":"SO6-1-u1-X30"}],"mis":"SO6-1-u1-X30","explanation":["어려움이 있었어요.","목소리가 커졌어요.","권리를 지키려 했어요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb),
('g6_1_soc_u1_review_d#23','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C16',4,'mc','auto','신문 ⑦과 ⑧을 함께 볼 때 산업화에 대한 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X27','SO6-1-u1-X28','SO6-1-u1-X29']::text[],false,'{"seq":23,"concept":"SO6-1-u1-C16","difficulty":4,"kind":"mc","stem":"신문 ⑦과 ⑧을 함께 볼 때 산업화에 대한 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 사람의 노력으로 산업이 발달해 생활이 크게 달라졌지만 그늘도 있어 함께 고쳐 왔다","correct":true},{"t":"산업화는 정부 혼자 이루었고 그늘은 없었다","mis":"SO6-1-u1-X27"},{"t":"산업이 발달해도 생활은 달라지지 않았다","mis":"SO6-1-u1-X28"},{"t":"산업화는 그늘만 남긴 일이다","mis":"SO6-1-u1-X29"}],"explanation":["⑦은 산업의 발달이에요.","⑧은 생활과 그늘이에요.","함께 고쳐 왔어요."]}'::jsonb),
('g6_1_soc_u1_review_d#24','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C14',4,'essay','teacher','신문 ⑦을 보고 할아버지가 일한 곳을 산업 발달의 흐름과 이어 쓰고, 산업화를 이끈 사람들의 노력을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u1-C14","difficulty":4,"kind":"essay","stem":"신문 ⑦을 보고 할아버지가 일한 곳을 산업 발달의 흐름과 이어 쓰고, 산업화를 이끈 사람들의 노력을 두 가지 쓰세요.","answer_guide":{"answer":"예: 할아버지는 1960년대 경공업이 발달할 때 신발 공장에서 일했고, 1970년대 중화학 공업이 발달할 때 조선소에서 배를 만들었다. 정부는 경제 개발 계획을 세우고 고속 국도와 항만, 연구소를 지었고, 독일로 간 광부와 간호사는 외화를 벌어 산업화의 밑거름을 만들었다.","scoring_points":["할아버지의 일터를 시대·산업과 이어 썼는가","경공업에서 중화학 공업으로의 흐름이 드러났는가","사람들의 노력 두 가지를 썼는가"]},"explanation":["신발은 경공업이에요.","배는 중화학 공업이에요.","여러 사람의 노력을 써요."],"asset":{"type":"passage","lines":["어릴 때 — 지원받은 밀가루로 만든 국수를 자주 드셨다.","청년 때 — 신발 공장에서 만든 신발이 배에 실려 외국으로 팔렸다.","그 뒤 — 큰 조선소에서 커다란 배를 만드는 일을 하셨다.","아빠가 어릴 때 — 우리 집에 자동차와 컬러텔레비전이 생겼다."],"title":"햇살반 역사 신문 ⑦ 할아버지의 일터"}}'::jsonb),
('g6_1_soc_u1_review_d#25','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C18',4,'essay','teacher','이 단원에서 공부한 사건 하나로 숨은 글씨 그림을 그린다고 생각하고, 사건·숨길 낱말·그릴 장면을 쓴 뒤 그 장면을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u1-C18","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 사건 하나로 숨은 글씨 그림을 그린다고 생각하고, 사건·숨길 낱말·그릴 장면을 쓴 뒤 그 장면을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 사건은 5·18 민주화 운동이고 숨길 낱말은 「알리다」이다. 카메라를 든 기자와 편지를 쓰는 시민들의 팔과 몸으로 글씨의 획을 만들고, 숨긴 글씨는 진하게 칠하겠다. 바깥과 막혀 있던 광주의 일을 시민과 기자들이 알리려 애썼기 때문에 진실을 알린 사람들의 모습을 골랐다.","scoring_points":["사건과 낱말을 썼는가","장면과 숨기는 방법을 썼는가","사건 내용과 이어 까닭을 썼는가"]},"explanation":["사건을 골라요.","장면 속에 숨겨요.","사건과 이어 까닭을 써요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO6-1-u2-C1','soc',6,1,'u2',1,'선거의 의미와 필요성 — 나라를 운영하려면 결정할 중요한 일이 많지만 모든 국민이 직접 참여해 나랏일을 결정하고 살림을 운영하기는 어려워 대표를 뽑아 일을 맡김 · 국민이 자신들을 대표할 사람을 투표로 뽑는 일이 선거 · 유권자는 선거에서 대표를 뽑을 권리를 가진 사람 · 선거로 뽑는 대표: 대통령·시장·군수·구청장·도지사·교육감 등 · 민주주의는 국민이 나라의 주인으로서 권리를 갖고 자유롭고 평등하게 행사하는 정치 형태 · 선거는 국민이 정치에 참여하고 주인으로서 권리를 행사하는 가장 기본적인 방법이라 민주주의의 꽃이라 부름',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],1),
('SO6-1-u2-C2','soc',6,1,'u2',2,'선거가 중요한 까닭 — 선거로 뽑힌 대표는 국민의 행복한 삶과 미래를 위해 나라의 중요한 일을 결정하고 헌법과 법률에 따라 일함 · 대표를 잘못 뽑으면 나라 경제나 국민의 삶이 어려워지고 민주주의가 위기를 맞을 수 있음 · 뽑아야 할 사람: 국민을 위해 열심히 일할 사람, 더 살기 좋은 환경을 위해 노력하는 사람, 도덕적으로 올바르고 공정한 사람 · 대표가 지역 발전을 위해 열심히 일하면 지역이 변화해 더 살기 좋은 환경이 됨',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],2),
('SO6-1-u2-C3','soc',6,1,'u2',2,'선거 참여와 국민 주권 — 국민 주권은 나라의 중요한 일을 결정하는 최고의 권력인 주권이 국민에게 있음 · 선거는 국민 주권을 실현하는 가장 기본적이고 중요한 방법이라 소중한 한 표를 행사해야 함 · 한 표 차이로 결과가 달라질 수 있고, 국민의 참여로 대표와 정치, 사회가 달라질 수 있음 · 재검표는 개표 결과에 잘못이나 실수가 있는지 확인하려고 다시 검사하는 일로, 결과를 바꾸는 일이 아니라 확인하는 일',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],3),
('SO6-1-u2-C4','soc',6,1,'u2',3,'선거 과정 — 선거는 법에 정해진 절차에 따라 공정하게 치름 · 선거인 명부 작성(선거 관리 위원회가 투표할 수 있는 사람의 명단을 만듦) → 후보자 등록 → 선거 운동(선거 공보·후보자 토론회·거리 유세 등) → 투표(신분 확인 → 투표용지 받기 → 투표하기 → 투표함에 넣기) → 개표(선거 관리 위원회가 투표함을 열어 결과 확인) → 당선자 결정 및 당선증 발급 · 앞 걸음이 만든 것이 뒤 걸음의 재료가 됨 · 선거 공보는 후보자의 기호·이름·사진·공약 등을 실은 문서 · 투표소를 두는 까닭은 누구나 같은 조건에서 공정하게 투표하고 결과를 조작하지 못하게 하려는 것',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],4),
('SO6-1-u2-C5','soc',6,1,'u2',3,'선거 원칙과 다양한 투표 방법 — 보통 선거(18세 이상이면 누구나), 평등 선거(모든 사람이 한 표씩), 직접 선거(투표권을 가진 사람이 직접), 비밀 선거(누구에게 투표했는지 알 수 없게) · 원칙을 정한 까닭: 공정하고 민주적인 선거, 모든 사람에게 동등한 권리 · 국민 누구나 원칙을 지켜야 하며 상황에 따라 바꾸지 않음 · 거소 투표(투표소에 가기 어려운 유권자가 머무는 곳에서), 선상 투표(배에 탄 선원이 배에서) — 모든 사람이 평등하게 참여하도록 선거권을 보장 · 선거 관리 위원회는 선거와 투표가 공정하게 이루어지도록 관리하는 국가기관',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],5),
('SO6-1-u2-C6','soc',6,1,'u2',4,'모의 선거와 공약 평가 — 후보자 정하기 → 공약 정하기 → 선거 운동(벽보·연설·토론회) → 공약 평가 → 투표 → 개표 → 당선자 발표 · 선거 벽보는 공약을 알려 유권자가 투표할 때 참고하게 함 · 공약을 재는 잣대: 구체적인가, 실천할 수 있는가, 국민의 요구를 반영하는가 — 후보자의 목소리·말솜씨, 상대 깎아내리기, 우리 모둠의 공약인지는 잣대가 될 수 없음 · 투표할 때: 공약을 꼼꼼히 살펴 한 후보자에게만, 누구를 뽑았는지 말하지 않음, 스스로 정함 · 선거 운동은 양보와 타협의 자세로 공정하고 정정당당하게',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],6),
('SO6-1-u2-C7','soc',6,1,'u2',5,'국가기관의 뜻과 있는 까닭 — 나랏일을 맡아 하는 곳이 국가기관 · 나라의 다양한 문제를 해결하려고 중요한 일을 결정하고 국민의 안전과 행복을 위해 일함 · 하는 일에 따라 국회(법을 만듦)·행정부(법에 따라 나라 살림을 맡음)·법원(법에 따라 판결)으로 나뉨 · 기관이 없으면 일상생활이 불편해지고 안전을 위협받으며 법을 지키지 않는 사람이 생길 수 있음 · 국가기관은 국민의 자유와 권리를 보장하기 위해 일함',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],7),
('SO6-1-u2-C8','soc',6,1,'u2',6,'국회와 법이 만들어지는 과정 — 국회는 국민의 뜻에 따라 나라 운영의 근거가 되는 법을 만들고 나랏일이 잘 운영되는지 감시하고 견제하는 국가기관 · 국회의원은 국민을 대신해 중요한 일을 결정하는 국민의 대표 · 국민의 요구 → 국회의원이 법률안 제출 → 국회에서 심의하고 투표하여 결정 → 대통령이 서명하여 널리 알리고 시행 · 법률안은 법률이 될 사항을 정리해 국회에 내는 문서 · 대통령은 의견이 다르면 거부권을 행사해 국회에서 다시 심의하게 할 수 있음(법을 만드는 자리와 마지막 서명 자리가 나뉨)',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],8),
('SO6-1-u2-C9','soc',6,1,'u2',6,'국회가 하는 다른 일 — 국정 감사(행정부가 법에 따라 나라를 잘 운영하는지 확인·감독하고 잘못을 바로잡도록 요구), 예산안 심의(한 해 나라 살림에 쓸 돈의 계획을 살펴 정하고 잘 썼는지 살핌), 인사 청문회(일을 맡을 사람이 알맞은 능력을 갖췄는지 살핌) · 모두 국민을 대표해서 하는 일',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],9),
('SO6-1-u2-C10','soc',6,1,'u2',7,'행정부의 구성 — 행정부는 국회에서 만든 법에 따라 나라의 살림을 맡아 하는 국가기관으로 국민의 안전하고 편리한 삶을 위해 일함 · 대통령(국민이 선출, 행정부의 최고 책임자이자 우리나라의 대표), 국무총리(대통령을 보좌하고 행정 각부를 관리하며 대통령이 임무를 수행할 수 없을 때 대신함), 행정 각부 · 자리가 비어도 대통령의 일은 사라지지 않고 국무총리가 대신 맡음(나라의 살림은 멈출 수 없음), 대신 맡는 동안에도 국무총리의 본래 몫은 그대로',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],10),
('SO6-1-u2-C11','soc',6,1,'u2',7,'행정 각부와 국무 회의 — 행정 각부는 경제·교육·외교·국방·환경 등의 업무를 나눠 맡아 다양한 일을 함(한 곳이 모든 일을 도맡지 않음) · 카드 뉴스 같은 홍보로 하는 일을 알림 · 국무 회의에서 대통령·국무총리·행정 각부의 장 등 국무 위원이 나라의 중요한 일이나 정책을 함께 의논함 · 행정부 조직은 새로 만들어지거나 이름이 바뀌기도 함',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],11),
('SO6-1-u2-C12','soc',6,1,'u2',8,'법원이 하는 일 — 사람들 사이에 다툼이 생기거나 범죄가 일어났을 때 재판을 통해 옳고 그름을 가리는 국가기관 · ① 개인 사이의 다툼 해결(층간 소음 피해 보상) ② 법을 어긴 사람을 처벌해 사회 질서 유지 ③ 개인과 국가·지방 자치 단체 사이의 갈등 해결(공사 피해 보상) · 피고인은 법을 어겼다고 판단해 재판에 세운 사람 · 법원이 없으면 다툼과 갈등의 옳고 그름을 가려 줄 곳이 없음',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],12),
('SO6-1-u2-C13','soc',6,1,'u2',8,'공정한 재판을 위한 제도 — 국민의 자유와 권리를 보장하려면 재판이 공정해야 함 · 법원의 독립과 법관의 신분 보장(외부 간섭 없이 판결) · 삼심 제도(하나의 사건에 원칙적으로 세 번까지 재판 — 잘못된 판결로 억울한 일을 막음, 1심 지방 법원 → 2심 고등 법원 → 3심 대법원, 판정이 달라질 수 있고 세 번이 상한) · 재판의 과정과 결과 공개(특별한 경우 제외) · 변호사는 법률 상담을 하고 의뢰인을 도와 변호함',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],13),
('SO6-1-u2-C14','soc',6,1,'u2',9,'권력 분립과 견제 — 권력이 한곳에 모이면 마음대로 쓰거나 잘못된 결정을 내려 국민의 자유와 권리가 침해받을 수 있음 · 권력 분립은 국가 권력을 국회·행정부·법원이 나눠 맡도록 헌법으로 정한 것 · 한 기관이 중요한 일을 마음대로 처리하지 못하도록 서로 견제하고 균형을 이룸 → 국민의 자유와 권리 보장 · 견제 사례: 국회 → 행정부(국정 감사), 대통령(행정부) → 국회(법률안 거부권), 법원 → 행정부(헌법에 어긋난 명령 취소) · 견제는 누가 나빠서가 아니라 서로 바로잡으려는 일 · 국민도 시민 단체 활동, 누리집 게시판 의견, 주민 투표로 대표를 물러나게 하는 제도 등으로 견제함',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],14),
('SO6-1-u2-C15','soc',6,1,'u2',10,'미디어의 뜻과 종류 — 미디어는 사람들이 정보를 주고받으며 의사소통하기 위해 사용하는 수단 · 겉모습(옛날 것인지, 종이인지, 걸어 두는지)이 아니라 정보를 주고받는 수단인지로 정함(옛 선거 공고문과 선거 안내 누리집은 둘 다 미디어) · 옛사람의 미디어: 벽화, 말을 타고 소식 전하기, 새 다리에 편지 묶기 등 · 오늘날: 전화·책·신문·방송·사회 관계망 서비스 등 · 신문(글과 사진으로 새로운 정보), 방송(영상과 소리로 다양한 정보) — 많은 사람에게 신속하게, 사회 관계망 서비스(글·음성·영상 등 다양한 형태로 주고받으며 의사소통)',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],15),
('SO6-1-u2-C16','soc',6,1,'u2',11,'민주주의에서 미디어의 역할 — 사람들이 함께 정할 때 필요한 정보를 얻게 하고 많은 사람에게 같은 정보를 한꺼번에 전함 · ① 많은 사람에게 영향을 미치는 새로운 사실을 신속하게 전함 ② 사회에서 중요하게 여기는 가치나 규범을 보여 주어 존중하는 태도를 기르게 함 ③ 사회문제를 지목하고 원인·영향·해결 방안을 제시해 여러 관점에서 이해하게 함 · 주고받는 정보와 생각이 의사 결정에 영향을 미쳐 중요 · 1인 미디어로 누구나 정보의 생산자가 되어 생각을 더 활발하게 나눔 · 안내소·파수꾼에 빗댈 수 있음',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],16),
('SO6-1-u2-C17','soc',6,1,'u2',12,'허위 조작 정보와 비판적 분석 — 허위 조작 정보는 사실과 다른 내용을 진짜처럼 꾸며 전하는 정보, 가짜 뉴스는 뉴스처럼 보이지만 거짓이거나 사실을 잘못 해석한 정보 · 생기는 까닭: 사실을 정확히 확인하지 않아서, 관심을 끌려고, 지지하는 쪽의 당선을 도우려고 · 사실과 다른 정보는 사람들의 권리를 침해하거나 사회 질서를 무너뜨릴 수 있음 · 여론은 많은 사람이 갖고 있는 공통된 의견 · 잘못된 여론은 합리적인 의사 결정을 방해해 민주주의를 위협 · 사실이 아니라고 밝혀져도 그 정보를 믿고 이미 정한 일은 되돌아오지 않음 → 미디어의 내용을 비판적으로 분석하여 이용',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],17),
('SO6-1-u2-C18','soc',6,1,'u2',13,'미디어를 올바르게 이용하는 태도 — 오보(사실 확인이 부족해 사실과 다른 정보를 전함)도 있어 보도라고 무조건 믿지 않고 다른 자료로 확인 · 같은 대상도 관점에 따라 다르게 전하므로 다양한 관점을 균형 있게 살핌 · 맞춤형 정보만 보면 관점이 다른 정보를 접하지 않아 편견이 강해짐 · 뉴스 형식을 흉내 낸 제목, 믿을 만한 사람이 전한 정보, 이름 검색 결과도 확인 · 검토 기준 넷: 뉴스 형식 흉내, 만든 사람과 날짜, 믿을 만한 출처, 타당한 근거 — 하나라도 걸리면 따져 봄(작성자와 날짜가 또렷해도 허위일 수 있음) · 이용 습관 점검·개선, 확인되지 않은 정보 공유하지 않기 · 미디어 비평가는 정확한 사실·균형·대안을 점검',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],18),
('SO6-1-u2-C19','soc',6,1,'u2',14,'뉴스 기사 쓰기와 검토 — 주제 고르기 → 조사하고 정리하기 → 기사 쓰기 → 기준에 따라 검토하기 · 기사가 될 만한 일: 최근에 생기거나 밝혀진 일, 영향을 받는 사람이 많은 일, 평범하거나 쉽게 겪을 수 없는 일(날마다 되풀이되는 일은 아님) · 설문지·인터넷 검색·면담으로 조사하고 출처를 함께 적으며 사실과 다르거나 왜곡된 내용은 적지 않음 · 기사 제목·작성일·작성자를 적음 · 검토 기준: 사실인가, 과장·왜곡이 있는가, 출처가 있는가, 같은 주제인데 다른 점이 있는가 · 무엇을 실을지는 사람마다 달라 같은 일도 기사가 달라짐 · 출처를 밝혀야 신뢰를 줌',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],19)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO6-1-u2-X01','soc',6,'u2',ARRAY['SO6-1-u2-C1']::text[],'우리나라에서는 모든 국민이 정치에 직접 참여해 나라의 일을 결정한다고 여겨 대표를 뽑는 까닭을 놓친다','모두 직접은 어려워 대표에게 맡겨요'),
('SO6-1-u2-X02','soc',6,'u2',ARRAY['SO6-1-u2-C1']::text[],'선거의 뜻이나 유권자의 뜻을 잘못 안다(대표를 추첨·임명으로 정한다고, 후보자를 유권자라고 여기는 등)','국민이 투표로 대표를 뽑아요'),
('SO6-1-u2-X03','soc',6,'u2',ARRAY['SO6-1-u2-C1']::text[],'민주주의의 뜻이나 선거를 민주주의의 꽃이라 부르는 까닭을 잘못 안다','국민이 주인 · 권리를 행사하는 기본 방법'),
('SO6-1-u2-X04','soc',6,'u2',ARRAY['SO6-1-u2-C2']::text[],'선거로 뽑힌 대표는 마음대로 일해도 되고 누가 뽑히든 나라와 지역에 달라질 것이 없다고 여긴다','헌법과 법률에 따라 · 잘못 뽑으면 어려워져요'),
('SO6-1-u2-X05','soc',6,'u2',ARRAY['SO6-1-u2-C2','SO6-1-u2-C6']::text[],'대표를 고르는 기준을 인기·말솜씨·겉모습처럼 공약이나 됨됨이와 관계없는 것에 둔다','국민을 위해 일할 사람 · 공정한 사람'),
('SO6-1-u2-X06','soc',6,'u2',ARRAY['SO6-1-u2-C3']::text[],'내 한 표로는 선거 결과가 달라지지 않는다고 여겨 참여의 중요성을 놓친다','한 표 차이로 달라질 수 있어요'),
('SO6-1-u2-X07','soc',6,'u2',ARRAY['SO6-1-u2-C3']::text[],'국민 주권의 뜻을 잘못 안다(주권이 대표나 정부에게 있다고 여기는 등)','주권은 국민에게 있어요'),
('SO6-1-u2-X08','soc',6,'u2',ARRAY['SO6-1-u2-C3']::text[],'재검표를 결과를 바꾸거나 다시 투표하는 일로 여긴다','잘못이 없는지 확인하는 일'),
('SO6-1-u2-X09','soc',6,'u2',ARRAY['SO6-1-u2-C4']::text[],'선거 과정의 차례를 뒤바꾼다(개표가 투표보다 먼저라고, 후보자 등록이 명부 작성보다 앞선다고 여기는 등)','명부 → 등록 → 운동 → 투표 → 개표 → 당선'),
('SO6-1-u2-X10','soc',6,'u2',ARRAY['SO6-1-u2-C4']::text[],'선거 과정의 걸음과 그 걸음에서 하는 일·하는 사람을 잘못 짝짓는다(개표를 후보자가 한다고 여기는 등)','선거 관리 위원회 · 후보자 · 유권자'),
('SO6-1-u2-X11','soc',6,'u2',ARRAY['SO6-1-u2-C4']::text[],'선거를 정해진 절차 없이 형편에 따라 치러도 된다고 여겨 법에 정해진 절차의 까닭(공정)을 놓친다','절차가 있어야 공정해요'),
('SO6-1-u2-X12','soc',6,'u2',ARRAY['SO6-1-u2-C5']::text[],'네 선거 원칙(보통·평등·직접·비밀)의 이름과 뜻을 바꾸어 짝짓는다','누구나 · 한 표씩 · 직접 · 비밀'),
('SO6-1-u2-X13','soc',6,'u2',ARRAY['SO6-1-u2-C5']::text[],'선거 원칙을 상황에 따라 바꿀 수 있다고 여기거나 원칙을 둔 까닭(공정·동등한 권리)을 놓친다','누구나 늘 지켜요'),
('SO6-1-u2-X14','soc',6,'u2',ARRAY['SO6-1-u2-C5']::text[],'투표소에 가기 어렵거나 배에 탄 유권자는 투표할 수 없다고 여겨 다양한 투표 방법을 놓친다','거소 투표 · 선상 투표'),
('SO6-1-u2-X15','soc',6,'u2',ARRAY['SO6-1-u2-C6']::text[],'공약을 재는 잣대가 아닌 것(후보자의 목소리·상대 깎아내리기·우리 모둠의 공약인지)을 잣대로 삼는다','구체적 · 실천 가능 · 국민의 요구'),
('SO6-1-u2-X16','soc',6,'u2',ARRAY['SO6-1-u2-C6','SO6-1-u2-C5']::text[],'투표할 때 지킬 점을 놓친다(친구와 함께 정해 똑같이 찍기, 여러 후보자에게 표시하기, 누구를 뽑았는지 말하기 등)','스스로 · 한 후보자에게만 · 비밀'),
('SO6-1-u2-X17','soc',6,'u2',ARRAY['SO6-1-u2-C7']::text[],'국가기관의 뜻이나 국가기관이 있는 까닭을 잘못 안다(일하는 사람 수·건물에 따라 나뉜다고, 기관이 없어도 일이 저절로 처리된다고 여기는 등)','하는 일에 따라 · 국민의 자유와 권리'),
('SO6-1-u2-X18','soc',6,'u2',ARRAY['SO6-1-u2-C7','SO6-1-u2-C8','SO6-1-u2-C10','SO6-1-u2-C12']::text[],'국회·행정부·법원이 하는 일을 서로 바꾸어 안다','법을 만듦 · 살림을 맡음 · 판결함'),
('SO6-1-u2-X19','soc',6,'u2',ARRAY['SO6-1-u2-C8']::text[],'법이 만들어지는 과정의 차례나 자리를 잘못 안다(대통령이 법을 만든다고, 국민의 요구 없이 시작된다고 여기는 등)','요구 → 법률안 → 심의·투표 → 서명'),
('SO6-1-u2-X20','soc',6,'u2',ARRAY['SO6-1-u2-C8']::text[],'대통령이 법률안에 서명하거나 되돌려 보내는 까닭을 잘못 안다(대통령이 법을 대신 만든다고, 되돌려 보내면 법이 사라진다고 여기는 등)','국회가 마음대로 못 하게 · 다시 심의'),
('SO6-1-u2-X21','soc',6,'u2',ARRAY['SO6-1-u2-C9']::text[],'국정 감사·예산안 심의·인사 청문회 같은 국회의 다른 일과 그 대상을 잘못 짝짓는다','살림 확인 · 나라 돈 계획 · 능력 확인'),
('SO6-1-u2-X22','soc',6,'u2',ARRAY['SO6-1-u2-C10']::text[],'대통령·국무총리·행정 각부의 역할을 바꾸어 알거나, 대통령 자리가 비면 그 일이 멈춘다고 여긴다','국무총리가 보좌하고 대신해요'),
('SO6-1-u2-X23','soc',6,'u2',ARRAY['SO6-1-u2-C11']::text[],'행정 각부와 국무 회의를 잘못 안다(한 부가 모든 업무를 도맡는다고, 각 부가 중요한 일을 따로 정한다고 여기는 등)','업무를 나눠 맡고 함께 의논해요'),
('SO6-1-u2-X24','soc',6,'u2',ARRAY['SO6-1-u2-C12']::text[],'법원이 하는 일을 장면과 잘못 짝짓거나, 재판의 목적(옳고 그름을 가려 질서 유지)을 놓친다','다툼 해결 · 처벌 · 국가와의 갈등'),
('SO6-1-u2-X25','soc',6,'u2',ARRAY['SO6-1-u2-C13']::text[],'공정한 재판을 위한 제도를 잘못 안다(재판을 모두 비공개로 한다고, 법원이 다른 기관과 협의해 판결한다고 여기는 등)','독립 · 세 번까지 · 공개'),
('SO6-1-u2-X26','soc',6,'u2',ARRAY['SO6-1-u2-C13']::text[],'삼심 제도를 잘못 안다(첫 판결로 끝난다고, 원하는 만큼 계속 재판받을 수 있다고, 다시 물어도 판결이 바뀌지 않는다고 여기는 등)','원칙적으로 세 번까지 · 바뀔 수 있어요'),
('SO6-1-u2-X27','soc',6,'u2',ARRAY['SO6-1-u2-C14']::text[],'권력이 한곳에 모일 때의 문제를 놓치거나 권력 분립의 뜻을 잘못 안다','마음대로 쓰면 자유와 권리가 침해돼요'),
('SO6-1-u2-X28','soc',6,'u2',ARRAY['SO6-1-u2-C14']::text[],'견제 사례에서 누가 누구를 견제하는지 바꾸어 안다','국정 감사 · 거부권 · 명령 취소'),
('SO6-1-u2-X29','soc',6,'u2',ARRAY['SO6-1-u2-C14']::text[],'권력을 나누는 까닭을 잘못 알거나(일을 빨리 하려고, 한 기관을 키우려고), 견제를 서로 미워하는 일로 여기거나, 국민도 견제할 수 있음을 놓친다','견제와 균형 · 국민의 자유와 권리'),
('SO6-1-u2-X30','soc',6,'u2',ARRAY['SO6-1-u2-C15']::text[],'미디어를 겉모습(종이인지·최신 기계인지·걸어 두는지)으로 정해, 정보를 주고받는 수단이라는 뜻을 놓친다','정보를 주고받는 수단인가'),
('SO6-1-u2-X31','soc',6,'u2',ARRAY['SO6-1-u2-C15']::text[],'신문·방송·사회 관계망 서비스 같은 미디어의 종류와 특징을 바꾸어 짝짓는다','글과 사진 · 영상과 소리 · 주고받기'),
('SO6-1-u2-X32','soc',6,'u2',ARRAY['SO6-1-u2-C16']::text[],'민주주의에서 미디어의 세 역할(새로운 사실·가치나 규범·사회문제와 해결 방안)을 사례와 잘못 짝짓는다','사실 · 가치 · 문제와 해결'),
('SO6-1-u2-X33','soc',6,'u2',ARRAY['SO6-1-u2-C16']::text[],'미디어가 사람들의 의사 결정에 영향을 미친다는 점이나, 1인 미디어로 누구나 정보를 만들 수 있다는 점을 놓친다','정보와 생각이 결정에 영향 · 누구나 생산자'),
('SO6-1-u2-X34','soc',6,'u2',ARRAY['SO6-1-u2-C17']::text[],'허위 조작 정보·가짜 뉴스·여론의 뜻을 잘못 안다','꾸민 정보 · 뉴스 흉내 · 공통된 의견'),
('SO6-1-u2-X35','soc',6,'u2',ARRAY['SO6-1-u2-C17']::text[],'사실이 아니라고 밝혀지면 그 정보로 생긴 피해도 모두 저절로 되돌아온다고 여겨, 미리 따져 봐야 하는 까닭을 놓친다','이미 정한 일은 남아요'),
('SO6-1-u2-X36','soc',6,'u2',ARRAY['SO6-1-u2-C17','SO6-1-u2-C18']::text[],'허위 조작 정보가 있으니 미디어를 아예 쓰지 말자거나 미디어가 전하는 정보는 모두 거짓이라고 여긴다','따져 보고 이용해요'),
('SO6-1-u2-X37','soc',6,'u2',ARRAY['SO6-1-u2-C18']::text[],'신문·방송에 보도된 것, 믿을 만한 사람이 전한 것, 작성자와 날짜가 적힌 것은 확인 없이 그대로 믿어도 된다고 여긴다','다른 자료로 확인 · 하나라도 걸리면'),
('SO6-1-u2-X38','soc',6,'u2',ARRAY['SO6-1-u2-C18']::text[],'맞춤형 정보나 내 관점에 맞는 정보만 보거나, 믿고 싶지 않은 정보를 확인 없이 거짓이라 정한다','다양한 관점을 균형 있게'),
('SO6-1-u2-X39','soc',6,'u2',ARRAY['SO6-1-u2-C19']::text[],'뉴스 기사가 될 만한 일의 조건을 잘못 알거나(날마다 되풀이되는 일), 같은 일은 누가 써도 기사가 같다고 여긴다','최근 · 영향 · 쉽게 겪을 수 없는 일'),
('SO6-1-u2-X40','soc',6,'u2',ARRAY['SO6-1-u2-C19']::text[],'기사를 쓰며 출처를 빼거나 사실을 부풀리고, 기준에 따른 검토를 놓친다','출처 · 사실 · 과장 없이')
